  function submissionPanel(d){if(!isOpd()||String(currentUser.opdId)!==String(d.lead_opd_id))return'';if(d.workflow_status==='ASSIGNED'||d.workflow_status==='REVISION_REQUIRED')return `<div class="border border-amber-500/20 bg-amber-500/5 rounded-xl p-4 mt-4"><h4 class="font-black text-sm">${d.workflow_status==='REVISION_REQUIRED'?'Revisi Diperlukan':'Tugas Siap Dikerjakan'}</h4>${d.workflow_status==='REVISION_REQUIRED'&&d.submissions?.[0]?.review_reason?`<p class="text-xs text-rose-300 mt-2">Catatan Humas: ${esc(d.submissions[0].review_reason)}</p>`:''}<button id="p3Start" class="mt-3 px-4 py-2 rounded-lg bg-amber-400 text-slate-950 font-black text-xs">${d.workflow_status==='REVISION_REQUIRED'?'Mulai Revisi':'Mulai Kerjakan'}</button></div>`;if(d.workflow_status!=='IN_PROGRESS')return'';return `<div class="border border-slate-800 rounded-xl p-4 mt-4"><h4 class="font-black text-sm">Susun Respons OPD</h4><label class="block text-xs text-slate-400 mt-3">Respons / Tindakan OPD <span class="text-rose-400 font-bold">* Wajib</span><span class="block text-[10px] text-slate-500 mt-1">Jelaskan jawaban resmi, tindakan, atau tindak lanjut OPD terhadap isu.</span><textarea id="p3Response" rows="5" class="mt-1 w-full rounded-lg p-3 bg-slate-950 border border-slate-700" placeholder="Jelaskan respons OPD terhadap isu...">${esc(d.submissions?.[0]?.status==='REVISION_REQUIRED'?d.submissions[0].response_text:'')}</textarea></label><label class="block text-xs text-slate-400 mt-3">Fakta & Data Pendukung <span class="text-rose-400 font-bold">* Wajib</span><span class="block text-[10px] text-slate-500 mt-1">Cantumkan fakta konkret seperti angka, tanggal, hasil kegiatan, progres, atau dasar kebijakan.</span><textarea id="p3Facts" rows="3" class="mt-1 w-full rounded-lg p-3 bg-slate-950 border border-slate-700">${esc(d.submissions?.[0]?.status==='REVISION_REQUIRED'?d.submissions[0].facts_data||'':'')}</textarea></label><label class="block text-xs text-slate-400 mt-3">Pesan Utama <span class="text-rose-400 font-bold">* Wajib</span><span class="block text-[10px] text-slate-500 mt-1">Tuliskan inti pesan singkat yang perlu diketahui publik dan dapat menjadi dasar narasi Humas.</span><textarea id="p3Key" rows="2" class="mt-1 w-full rounded-lg p-3 bg-slate-950 border border-slate-700">${esc(d.submissions?.[0]?.status==='REVISION_REQUIRED'?d.submissions[0].key_message||'':'')}</textarea></label><label class="block text-xs text-slate-400 mt-3">Bukti Dukung <span class="text-slate-500">(Opsional · maks. 5 link, satu URL per baris)</span><span class="block text-[10px] text-slate-500 mt-1">Tautan dokumen, berita resmi, data, atau sumber lain yang mendukung respons OPD.</span><textarea id="p3Links" rows="2" class="mt-1 w-full rounded-lg p-3 bg-slate-950 border border-slate-700"></textarea></label><button id="p3Submit" class="mt-3 px-4 py-2 rounded-lg bg-emerald-400 text-slate-950 font-black text-xs">Kirim ke Humas</button></div>`}

  function contributorClarificationPanel(d){if(!isOpd()||String(currentUser.opdId)!==String(d.lead_opd_id)||d.workflow_status!=='IN_PROGRESS')return'';const rows=d.contributors||[];if(!rows.length)return'';const label=x=>x.opd_name||x.uptd_name||x.district_name||x.contributor_type;return `<div class="border border-violet-500/20 bg-violet-500/5 rounded-xl p-4 mt-4"><h4 class="font-black text-sm">Klarifikasi Kontributor</h4><p class="text-[10px] text-slate-500 mt-1">Humas menunjuk calon kontributor. Lead OPD menentukan apakah klarifikasi mereka diperlukan.</p><div class="space-y-3 mt-3">${rows.map(x=>{const latest=(d.clarificationRounds||[]).filter(r=>String(r.contributor_assignment_id)===String(x.id))[0];const submitted=(d.contributorSubmissions||[]).find(s=>latest&&String(s.id)===String(latest.submission_id));return `<div class="rounded-lg border border-slate-800 bg-slate-950/60 p-3 text-xs"><div class="flex justify-between gap-2"><b>${esc(label(x))}</b><span class="text-[10px] text-slate-400">${esc(x.status)}</span></div>${latest?`<div class="mt-2 text-slate-400"><b>Permintaan #${latest.round_number}:</b> ${esc(latest.request_text)}</div>`:''}${x.contributor_type==='UPTD'&&x.status==='CLARIFICATION_REQUESTED'?`<div class="mt-3 rounded-lg border border-cyan-500/20 bg-cyan-500/5 p-3"><div class="font-bold text-cyan-200">Input klarifikasi atas nama ${esc(x.uptd_name||'UPTD')}</div><div class="text-[10px] text-slate-500 mt-1">UPTD tidak memiliki akun. Lead OPD memasukkan keterangan yang diterima dari UPTD.</div><textarea data-uptd-field="${x.id}" rows="2" placeholder="Keterangan / kondisi teknis" class="mt-2 w-full rounded-lg p-2 bg-slate-950 border border-slate-700"></textarea><textarea data-uptd-facts="${x.id}" rows="2" placeholder="Fakta & data" class="mt-2 w-full rounded-lg p-2 bg-slate-950 border border-slate-700"></textarea><textarea data-uptd-action="${x.id}" rows="2" placeholder="Tindakan yang sudah dilakukan" class="mt-2 w-full rounded-lg p-2 bg-slate-950 border border-slate-700"></textarea><textarea data-uptd-notes="${x.id}" rows="2" placeholder="Catatan" class="mt-2 w-full rounded-lg p-2 bg-slate-950 border border-slate-700"></textarea><textarea data-uptd-links="${x.id}" rows="2" placeholder="Bukti dukung URL, satu per baris · maks. 5" class="mt-2 w-full rounded-lg p-2 bg-slate-950 border border-slate-700"></textarea><button data-p3-uptd-submit="${x.id}" class="mt-2 px-3 py-2 rounded-lg bg-cyan-400 text-slate-950 font-black text-xs">Simpan Klarifikasi UPTD</button></div>`:''}${submitted?contributorCards([submitted]):''}<div class="mt-3 flex flex-wrap gap-2">${x.status==='NOMINATED'?`<button data-p3-request="${x.id}" class="px-3 py-2 rounded-lg bg-violet-400 text-slate-950 font-black text-xs">Minta Klarifikasi</button>`:''}${x.status==='SUBMITTED'?`<button data-p3-accept="${x.id}" class="px-3 py-2 rounded-lg bg-emerald-400 text-slate-950 font-black text-xs">Terima Klarifikasi</button><button data-p3-followup="${x.id}" class="px-3 py-2 rounded-lg bg-amber-400 text-slate-950 font-black text-xs">Minta Klarifikasi Lanjutan</button>`:''}${x.status==='CLARIFICATION_REQUESTED'?'<span class="text-cyan-300">Menunggu klarifikasi kontributor.</span>':''}${x.status==='ACCEPTED'?'<span class="text-emerald-300">Klarifikasi diterima · selesai.</span>':''}</div></div>`}).join('')}</div></div>`}

  function supportingOpdClarificationPanel(d){if(!isOpd()||String(currentUser.opdId)===String(d.lead_opd_id))return'';const a=(d.contributors||[]).find(x=>x.contributor_type==='OPD'&&String(x.opd_id)===String(currentUser.opdId));if(!a)return'';const round=(d.clarificationRounds||[]).find(x=>String(x.contributor_assignment_id)===String(a.id));const mine=(d.contributorSubmissions||[]).filter(x=>String(x.contributor_assignment_id)===String(a.id));if(a.status!=='CLARIFICATION_REQUESTED')return `<div class="border border-slate-800 rounded-xl p-4 mt-4"><h4 class="font-black text-sm">Permintaan Klarifikasi</h4><p class="text-xs text-slate-400 mt-2">${a.status==='NOMINATED'?'OPD Anda ditunjuk Humas sebagai OPD Pembantu. Belum ada permintaan klarifikasi dari Lead OPD.':a.status==='SUBMITTED'?'Klarifikasi sudah dikirim dan menunggu review Lead OPD.':a.status==='ACCEPTED'?'Klarifikasi telah diterima Lead OPD.':'Tidak ada klarifikasi aktif.'}</p>${mine.length?contributorCards(mine):''}</div>`;return `<div class="border border-violet-500/20 bg-violet-500/5 rounded-xl p-4 mt-4"><h4 class="font-black text-sm">Permintaan Klarifikasi dari Lead OPD</h4><p class="text-xs text-violet-200 mt-2">${round?esc(round.request_text):'Lead OPD meminta klarifikasi.'}</p><p class="text-[10px] text-slate-500 mt-1">Jawaban ini merupakan bahan klarifikasi OPD Pembantu, bukan respons resmi final Issue.</p><label class="block text-xs text-slate-400 mt-3">Keterangan / Kondisi<textarea id="p3SupportCondition" rows="3" class="mt-1 w-full rounded-lg p-3 bg-slate-950 border border-slate-700"></textarea></label><label class="block text-xs text-slate-400 mt-3">Fakta & Data<textarea id="p3SupportFacts" rows="3" class="mt-1 w-full rounded-lg p-3 bg-slate-950 border border-slate-700"></textarea></label><label class="block text-xs text-slate-400 mt-3">Tindakan / Informasi Teknis<textarea id="p3SupportAction" rows="3" class="mt-1 w-full rounded-lg p-3 bg-slate-950 border border-slate-700"></textarea></label><label class="block text-xs text-slate-400 mt-3">Catatan <span class="text-slate-500">· dapat menyebut sumber UPTD bila ada</span><textarea id="p3SupportNotes" rows="2" class="mt-1 w-full rounded-lg p-3 bg-slate-950 border border-slate-700"></textarea></label><label class="block text-xs text-slate-400 mt-3">Bukti Dukung <span class="text-slate-500">(maks. 5 URL)</span><textarea id="p3SupportLinks" rows="2" class="mt-1 w-full rounded-lg p-3 bg-slate-950 border border-slate-700"></textarea></label><button id="p3SupportSubmit" data-assignment="${a.id}" class="mt-3 px-4 py-2 rounded-lg bg-violet-400 text-slate-950 font-black text-xs">Kirim Klarifikasi ke Lead OPD</button>${mine.length?contributorCards(mine):''}</div>`}

  function districtContributionPanel(d){if(!isDistrict())return'';const a=d.access||{},assignment=(d.contributors||[]).find(x=>x.contributor_type==='DISTRICT'&&String(x.district_id)===String(a.districtId)),round=(d.clarificationRounds||[]).find(x=>assignment&&String(x.contributor_assignment_id)===String(assignment.id));if(!a.districtAssigned)return `<div class="border border-slate-800 bg-slate-950/40 rounded-xl p-4 mt-4"><h4 class="font-black text-sm">Klarifikasi Lapangan Kecamatan</h4><p class="text-xs text-slate-400 mt-2">Issue ini berada dalam wilayah Anda, tetapi Kecamatan belum ditugaskan Humas sebagai kontributor. Akses saat ini hanya untuk pemantauan.</p></div>`;const mine=(d.contributorSubmissions||[]).filter(x=>String(x.district_id)===String(a.districtId));if(!a.canContributeDistrict)return `<div class="border border-slate-800 rounded-xl p-4 mt-4"><h4 class="font-black text-sm">Klarifikasi Lapangan Kecamatan</h4><p class="text-xs text-slate-400 mt-2">${assignment?.status==='NOMINATED'?'Kecamatan telah ditunjuk Humas. Menunggu Lead OPD memutuskan apakah klarifikasi diperlukan.':assignment?.status==='SUBMITTED'?'Klarifikasi telah dikirim dan sedang menunggu review Lead OPD.':assignment?.status==='ACCEPTED'?'Klarifikasi telah diterima Lead OPD. Tidak ada tindakan lanjutan.':'Klarifikasi belum dapat dikirim pada status workflow saat ini.'}</p>${mine.length?contributorCards(mine):''}</div>`;return `<div class="border border-cyan-500/20 bg-cyan-500/5 rounded-xl p-4 mt-4"><h4 class="font-black text-sm">Klarifikasi Lapangan Kecamatan</h4><p class="text-xs text-slate-400 mt-1">Lead OPD meminta klarifikasi dari Kecamatan.${round?` Permintaan #${round.round_number}: ${esc(round.request_text)}`:''} Informasi yang dikirim menjadi bahan Lead OPD dan bukan respons resmi final.</p><label class="block text-xs text-slate-400 mt-3">Kondisi Lapangan<textarea id="p3DistrictCondition" rows="3" class="mt-1 w-full rounded-lg p-3 bg-slate-950 border border-slate-700"></textarea></label><label class="block text-xs text-slate-400 mt-3">Fakta & Data<textarea id="p3DistrictFacts" rows="3" class="mt-1 w-full rounded-lg p-3 bg-slate-950 border border-slate-700"></textarea></label><label class="block text-xs text-slate-400 mt-3">Tindakan yang Sudah Dilakukan<textarea id="p3DistrictAction" rows="3" class="mt-1 w-full rounded-lg p-3 bg-slate-950 border border-slate-700"></textarea></label><label class="block text-xs text-slate-400 mt-3">Catatan<textarea id="p3DistrictNotes" rows="2" class="mt-1 w-full rounded-lg p-3 bg-slate-950 border border-slate-700"></textarea></label><label class="block text-xs text-slate-400 mt-3">Bukti Dukung <span class="text-slate-500">(opsional · maks. 5 URL, satu per baris)</span><textarea id="p3DistrictLinks" rows="2" class="mt-1 w-full rounded-lg p-3 bg-slate-950 border border-slate-700"></textarea></label><button id="p3DistrictSubmit" class="mt-3 px-4 py-2 rounded-lg bg-cyan-400 text-slate-950 font-black text-xs">Kirim Klarifikasi ke Lead OPD</button>${mine.length?contributorCards(mine):''}</div>`}
  function contributorCards(rows){return `<div class="mt-4"><div class="text-[10px] font-black tracking-wider text-slate-500">KLARIFIKASI KONTRIBUTOR</div><div class="space-y-2 mt-2">${rows.map(x=>`<div class="rounded-lg border border-slate-800 bg-slate-950/60 p-3 text-xs"><div class="flex justify-between gap-2"><b>${esc(x.opd_name||x.district_name||x.uptd_name||x.contributor_type)}</b><span class="text-[10px] text-slate-500">${fmt(x.created_at)}</span></div>${x.field_condition?`<div class="mt-2"><span class="text-slate-500">Kondisi:</span> ${esc(x.field_condition)}</div>`:''}${x.facts_data?`<div class="mt-2"><span class="text-slate-500">Fakta/Data:</span> ${esc(x.facts_data)}</div>`:''}${x.action_taken?`<div class="mt-2"><span class="text-slate-500">Tindakan:</span> ${esc(x.action_taken)}</div>`:''}${x.notes?`<div class="mt-2"><span class="text-slate-500">Catatan:</span> ${esc(x.notes)}</div>`:''}${Array.isArray(x.supporting_links)&&x.supporting_links.length?`<div class="mt-2">${x.supporting_links.map((u,i)=>`<a class="block text-cyan-300 underline break-all" href="${esc(u)}" target="_blank" rel="noopener noreferrer">Bukti ${i+1}</a>`).join('')}</div>`:''}</div>`).join('')}</div></div>`}
  function contributorPanel(d){if(isDistrict())return'';const rows=d.contributorSubmissions||[];return rows.length?`<div class="border border-slate-800 rounded-xl p-4 mt-4"><h4 class="font-black text-sm">Masukan Kontributor</h4><p class="text-[10px] text-slate-500 mt-1">Bahan klarifikasi dari OPD Pembantu, Kecamatan, dan UPTD Lead. Klarifikasi tidak otomatis menjadi respons resmi.</p>${contributorCards(rows)}</div>`:''}
  function clarificationHistoryPanel(d){if(!isHumas())return'';const rounds=d.clarificationRounds||[];if(!rounds.length)return'';const submissions=d.contributorSubmissions||[];return `<div class="border border-slate-800 rounded-xl p-4 mt-4"><h4 class="font-black text-sm">Riwayat Klarifikasi Kontributor</h4><p class="text-[10px] text-slate-500 mt-1">Audit baca-saja untuk Humas. Keputusan menerima atau meminta klarifikasi lanjutan tetap kewenangan Lead OPD.</p><div class="space-y-3 mt-3">${rounds.map(r=>{const s=submissions.find(x=>String(x.id)===String(r.submission_id));const name=r.opd_name||r.uptd_name||r.district_name||r.contributor_type;return `<div class="rounded-lg border border-slate-800 bg-slate-950/60 p-3 text-xs"><div class="flex flex-wrap justify-between gap-2"><b>${esc(name)} · Klarifikasi #${esc(r.round_number)}</b><span class="text-[10px] text-slate-400">${esc(r.review_status)}</span></div><div class="mt-2"><span class="text-slate-500">Permintaan Lead:</span> ${esc(r.request_text)}</div><div class="text-[10px] text-slate-600 mt-1">${fmt(r.requested_at)} · ${esc(r.requested_by_email||'catatan legacy/sistem')}</div>${s?contributorCards([s]):''}${r.review_note?`<div class="mt-2"><span class="text-slate-500">Catatan review Lead:</span> ${esc(r.review_note)}</div>`:''}${r.reviewed_at?`<div class="text-[10px] text-slate-600 mt-1">Direview ${fmt(r.reviewed_at)} · ${esc(r.reviewed_by_email||'Lead OPD')}</div>`:''}</div>`}).join('')}</div></div>`}
  function finalResponsePanel(d){
    if(!['APPROVED','PUBLISHED','MONITORING','CLOSED'].includes(d.workflow_status))return'';
    const s=d.submissions?.find(x=>x.status==='APPROVED')||d.submissions?.[0];if(!s)return'';
    return `<div class="border border-emerald-500/20 bg-emerald-500/5 rounded-xl p-4 mt-4"><div class="flex justify-between gap-2"><h4 class="font-black text-sm">Respons OPD Disetujui</h4><span class="text-[10px] text-emerald-300">Versi ${esc(s.version)}</span></div><div class="mt-3 space-y-3 text-xs"><div><div class="text-slate-500">Respons / Tindakan OPD</div><div class="mt-1 whitespace-pre-wrap">${esc(s.response_text)}</div></div><div><div class="text-slate-500">Fakta & Data Pendukung</div><div class="mt-1 whitespace-pre-wrap">${esc(s.facts_data||'-')}</div></div><div><div class="text-slate-500">Pesan Utama</div><div class="mt-1 whitespace-pre-wrap">${esc(s.key_message||'-')}</div></div>${Array.isArray(s.supporting_links)&&s.supporting_links.length?`<div><div class="text-slate-500">Bukti Dukung</div><div class="mt-1 space-y-1">${s.supporting_links.map((u,i)=>`<a class="block text-cyan-300 underline break-all" href="${esc(u)}" target="_blank" rel="noopener noreferrer">Link ${i+1}: ${esc(u)}</a>`).join('')}</div></div>`:''}</div><div class="text-[10px] text-slate-500 mt-3">Respons final bersifat baca-saja setelah disetujui Humas.</div></div>`;
  }
  function reviewPanel(d){if(!isHumas()||d.workflow_status!=='SUBMITTED')return'';const s=d.submissions?.find(x=>x.status==='SUBMITTED')||d.submissions?.[0];if(!s)return'';return `<div class="border border-violet-500/20 bg-violet-500/5 rounded-xl p-4 mt-4"><div class="flex justify-between gap-2"><h4 class="font-black text-sm">Review Respons OPD</h4><span class="text-[10px] text-violet-300">Versi ${esc(s.version)}</span></div><div class="mt-3 space-y-3 text-xs"><div><div class="text-slate-500">Respons / Tindakan OPD</div><div class="mt-1 whitespace-pre-wrap">${esc(s.response_text)}</div></div>${s.facts_data?`<div><div class="text-slate-500">Fakta & Data Pendukung</div><div class="mt-1 whitespace-pre-wrap">${esc(s.facts_data)}</div></div>`:''}${s.key_message?`<div><div class="text-slate-500">Pesan Utama</div><div class="mt-1 whitespace-pre-wrap">${esc(s.key_message)}</div></div>`:''}${Array.isArray(s.supporting_links)&&s.supporting_links.length?`<div><div class="text-slate-500">Bukti Dukung</div><div class="mt-1 space-y-1">${s.supporting_links.map((u,i)=>`<a class="block text-cyan-300 underline break-all" href="${esc(u)}" target="_blank" rel="noopener noreferrer">Link ${i+1}: ${esc(u)}</a>`).join('')}</div></div>`:''}</div><div class="flex flex-wrap gap-2 mt-4"><button id="p3Approve" class="px-4 py-2 rounded-lg bg-emerald-400 text-slate-950 font-black text-xs">Setujui Respons</button><button id="p3Revision" class="px-4 py-2 rounded-lg bg-rose-500/15 border border-rose-500/30 text-rose-300 font-black text-xs">Minta Revisi</button></div></div>`}
  function renderDetail(){const box=document.getElementById('p3Detail');if(!box||!detail)return;const d=detail;box.innerHTML=`<div class="flex flex-wrap justify-between gap-3"><div class="min-w-0"><div class="flex items-center gap-2">${badge(d.workflow_status)}<span class="text-[10px] text-slate-500">Issue #${esc(d.issue_id)}</span></div><h3 class="text-xl font-black mt-2">${esc(d.title)}</h3><p class="text-xs text-slate-400 mt-2 whitespace-pre-wrap">${esc(d.description||'Belum ada deskripsi isu.')}</p></div></div><div class="grid md:grid-cols-2 xl:grid-cols-4 gap-3 mt-4"><div class="bg-slate-950/70 rounded-xl p-3"><div class="text-[10px] text-slate-500">Lead OPD</div><div class="text-sm font-bold mt-1">${esc(d.lead_opd_name||recommendation?.opds?.primary?.name||'Belum ditetapkan')}</div>${!d.lead_opd_name&&recommendation?.opds?.primary?.name?`<div class="text-[10px] text-cyan-400 mt-1">Rekomendasi · belum ditugaskan</div>`:''}</div><div class="bg-slate-950/70 rounded-xl p-3"><div class="text-[10px] text-slate-500">Batas Waktu Respons OPD</div><div class="text-sm font-bold mt-1">${fmt(d.due_at)}</div>${lateInfo(d)?`<div class="mt-1 text-[10px] font-bold text-rose-300"><i class="fa-solid fa-clock mr-1"></i>${lateInfo(d).submitted?'Dikirim terlambat':'Terlambat'} ${esc(lateInfo(d).text)}</div>`:''}</div><div class="bg-slate-950/70 rounded-xl p-3"><div class="text-[10px] text-slate-500">Supporting OPD</div><div class="text-sm font-bold mt-1">${(d.supportingOpds||[]).map(x=>esc(x.name)).join(', ')||'Belum dipilih'}</div></div><div class="bg-slate-950/70 rounded-xl p-3"><div class="text-[10px] text-slate-500">Wilayah Issue</div><div class="text-sm font-bold mt-1">${teamOptions?.geographicScope==='CITYWIDE'?'Seluruh Kota Batam':teamOptions?.geographicScope==='DISTRICTS'?(teamOptions?.districtContributors||[]).filter(x=>x.in_issue_scope).map(x=>esc(x.name)).join(', ')||'Belum ditetapkan':'Belum ditetapkan'}</div></div></div>${gapContextPanel()}${assignmentPanel(d)}${supportingOpdClarificationPanel(d)}${districtContributionPanel(d)}${contributorClarificationPanel(d)}${clarificationHistoryPanel(d)}${contributorPanel(d)}${submissionPanel(d)}${reviewPanel(d)}${finalResponsePanel(d)}<div class="border-t border-slate-800 mt-5 pt-4"><h4 class="font-black text-sm">Riwayat Workflow</h4><div class="mt-3 space-y-2">${events.map(e=>`<div class="bg-slate-950/60 rounded-lg p-3 text-xs"><div class="flex justify-between gap-2"><b>${esc(String(e.event_type||'').replaceAll('_',' '))}</b><span class="text-slate-500">${fmt(e.created_at)}</span></div>${e.note?`<div class="text-slate-400 mt-1">${esc(e.note)}</div>`:''}<div class="text-[10px] text-slate-600 mt-1">${esc(e.actor_email||e.actor_role||'system')}</div></div>`).join('')||'<div class="text-xs text-slate-500">Belum ada event.</div>'}</div></div>`;bindActions()}
  function bindActions(){const d=detail;document.querySelectorAll('[data-p3-uptd-submit]').forEach(btn=>btn.onclick=async()=>{const id=btn.dataset.p3UptdSubmit,fieldCondition=document.querySelector(`[data-uptd-field="${id}"]`).value.trim(),factsData=document.querySelector(`[data-uptd-facts="${id}"]`).value.trim(),actionTaken=document.querySelector(`[data-uptd-action="${id}"]`).value.trim(),notes=document.querySelector(`[data-uptd-notes="${id}"]`).value.trim(),supportingLinks=document.querySelector(`[data-uptd-links="${id}"]`).value.split(/\n+/).map(x=>x.trim()).filter(Boolean);if(!fieldCondition&&!factsData&&!actionTaken&&!notes)return toast('Isi minimal satu bagian klarifikasi UPTD.',false);if(supportingLinks.length>5)return toast('Maksimal 5 bukti dukung.',false);const old=btn.innerHTML;btn.disabled=true;btn.innerHTML='<i class="fa-solid fa-spinner fa-spin mr-2"></i>Menyimpan...';try{await api(`/phase3/issues/${d.issue_id}/uptd-contribution`,{method:'POST',body:JSON.stringify({contributorAssignmentId:Number(id),fieldCondition:fieldCondition||null,factsData:factsData||null,actionTaken:actionTaken||null,notes:notes||null,supportingLinks})});toast('Klarifikasi UPTD disimpan.');await load(true)}catch(e){btn.disabled=false;btn.innerHTML=old;toast(e.message,false)}});document.querySelectorAll('[data-p3-request]').forEach(btn=>btn.onclick=async()=>{const requestText=prompt('Apa yang perlu diklarifikasi oleh kontributor?');if(!requestText?.trim())return;try{await api(`/phase3/issues/${d.issue_id}/contributors/request-clarification`,{method:'POST',body:JSON.stringify({contributorAssignmentId:Number(btn.dataset.p3Request),requestText:requestText.trim()})});toast('Permintaan klarifikasi dikirim.');await load(true)}catch(e){toast(e.message,false)}});document.querySelectorAll('[data-p3-accept]').forEach(btn=>btn.onclick=async()=>{if(!confirm('Terima klarifikasi ini dan tutup kebutuhan klarifikasi kontributor?'))return;try{await api(`/phase3/issues/${d.issue_id}/contributors/review-clarification`,{method:'POST',body:JSON.stringify({contributorAssignmentId:Number(btn.dataset.p3Accept),decision:'ACCEPTED',note:null})});toast('Klarifikasi diterima.');await load(true)}catch(e){toast(e.message,false)}});document.querySelectorAll('[data-p3-followup]').forEach(btn=>btn.onclick=async()=>{const note=prompt('Tuliskan klarifikasi lanjutan yang dibutuhkan:');if(!note?.trim())return;try{await api(`/phase3/issues/${d.issue_id}/contributors/review-clarification`,{method:'POST',body:JSON.stringify({contributorAssignmentId:Number(btn.dataset.p3Followup),decision:'FOLLOW_UP_REQUESTED',note:note.trim()})});toast('Klarifikasi lanjutan diminta.');await load(true)}catch(e){toast(e.message,false)}});if(document.getElementById('p3Assign'))document.getElementById('p3Assign').onclick=async()=>{const btn=document.getElementById('p3Assign');if(btn.disabled)return;const support=[...document.querySelectorAll('[data-p3-support]:checked')].map(o=>Number(o.value));const supportingUptdIds=[...document.querySelectorAll('[data-p3-uptd]:checked')].map(x=>Number(x.value));const districtContributorIds=[...document.querySelectorAll('[data-p3-district]:checked')].map(x=>Number(x.value));const due=document.getElementById('p3Due').value,old=btn.innerHTML;btn.disabled=true;btn.classList.add('opacity-70','cursor-wait');btn.innerHTML='<i class="fa-solid fa-spinner fa-spin mr-2"></i>Memproses penugasan...';try{await api(`/phase3/issues/${d.issue_id}/assign`,{method:'POST',body:JSON.stringify({supportingOpdIds:support,supportingUptdIds,districtContributorIds,dueAt:due?new Date(due).toISOString():null})});toast('Penugasan disimpan.');await load(true)}catch(e){btn.disabled=false;btn.classList.remove('opacity-70','cursor-wait');btn.innerHTML=old;toast(e.message,false)}};if(document.getElementById('p3Start'))document.getElementById('p3Start').onclick=async()=>{try{await api(`/phase3/issues/${d.issue_id}/start`,{method:'POST'});toast('Pekerjaan dimulai.');await load(true)}catch(e){toast(e.message,false)}};if(document.getElementById('p3Submit'))document.getElementById('p3Submit').onclick=async()=>{const responseText=document.getElementById('p3Response').value.trim();if(responseText.length<10)return toast('Respons minimal 10 karakter.',false);const factsData=document.getElementById('p3Facts').value.trim(),keyMessage=document.getElementById('p3Key').value.trim();if(!factsData)return toast('Fakta & Data Pendukung wajib diisi.',false);if(!keyMessage)return toast('Pesan Utama wajib diisi.',false);const supportingLinks=document.getElementById('p3Links').value.split(/\n+/).map(x=>x.trim()).filter(Boolean);if(supportingLinks.length>5)return toast('Maksimal 5 supporting link.',false);try{await api(`/phase3/issues/${d.issue_id}/submit`,{method:'POST',body:JSON.stringify({responseText,factsData,keyMessage,supportingLinks})});toast('Respons dikirim ke Humas.');await load(true)}catch(e){toast(e.message,false)}};if(document.getElementById('p3Approve'))document.getElementById('p3Approve').onclick=async()=>{if(!confirm('Setujui respons OPD ini?'))return;try{await api(`/phase3/issues/${d.issue_id}/review`,{method:'POST',body:JSON.stringify({decision:'APPROVED',reason:null})});toast('Respons disetujui.');await load(true)}catch(e){toast(e.message,false)}};if(document.getElementById('p3SupportSubmit'))document.getElementById('p3SupportSubmit').onclick=async()=>{const btn=document.getElementById('p3SupportSubmit'),fieldCondition=document.getElementById('p3SupportCondition').value.trim(),factsData=document.getElementById('p3SupportFacts').value.trim(),actionTaken=document.getElementById('p3SupportAction').value.trim(),notes=document.getElementById('p3SupportNotes').value.trim(),supportingLinks=document.getElementById('p3SupportLinks').value.split(/\n+/).map(x=>x.trim()).filter(Boolean);if(!fieldCondition&&!factsData&&!actionTaken&&!notes)return toast('Isi minimal satu bagian klarifikasi.',false);if(supportingLinks.length>5)return toast('Maksimal 5 bukti dukung.',false);try{await api(`/phase3/issues/${d.issue_id}/supporting-opd-contribution`,{method:'POST',body:JSON.stringify({contributorAssignmentId:Number(btn.dataset.assignment),fieldCondition:fieldCondition||null,factsData:factsData||null,actionTaken:actionTaken||null,notes:notes||null,supportingLinks})});toast('Klarifikasi dikirim ke Lead OPD.');await load(true)}catch(e){toast(e.message,false)}};if(document.getElementById('p3DistrictSubmit'))document.getElementById('p3DistrictSubmit').onclick=async()=>{const fieldCondition=document.getElementById('p3DistrictCondition').value.trim(),factsData=document.getElementById('p3DistrictFacts').value.trim(),actionTaken=document.getElementById('p3DistrictAction').value.trim(),notes=document.getElementById('p3DistrictNotes').value.trim(),supportingLinks=document.getElementById('p3DistrictLinks').value.split(/\n+/).map(x=>x.trim()).filter(Boolean);if(!fieldCondition&&!factsData&&!actionTaken&&!notes)return toast('Isi minimal satu bagian klarifikasi.',false);if(supportingLinks.length>5)return toast('Maksimal 5 bukti dukung.',false);const btn=document.getElementById('p3DistrictSubmit'),old=btn.innerHTML;btn.disabled=true;btn.innerHTML='<i class="fa-solid fa-spinner fa-spin mr-2"></i>Mengirim...';try{await api(`/phase3/issues/${d.issue_id}/district-contribution`,{method:'POST',body:JSON.stringify({fieldCondition:fieldCondition||null,factsData:factsData||null,actionTaken:actionTaken||null,notes:notes||null,supportingLinks})});toast('Klarifikasi Kecamatan dikirim ke Lead OPD.');await load(true)}catch(e){btn.disabled=false;btn.innerHTML=old;toast(e.message,false)}};if(document.getElementById('p3Revision'))document.getElementById('p3Revision').onclick=async()=>{const reason=prompt('Alasan revisi:');if(!reason?.trim())return;try{await api(`/phase3/issues/${d.issue_id}/review`,{method:'POST',body:JSON.stringify({decision:'REVISION_REQUIRED',reason:reason.trim()})});toast('Respons dikembalikan untuk revisi.');await load(true)}catch(e){toast(e.message,false)}}}
  async function selectIssue(id){selectedIssueId=id;renderList();try{const cached=detailCache.get(String(id)),cachedCtx=contextCache.get(String(id));if(cached){detail=cached.detail;events=cached.events;recommendation=cachedCtx||null;teamOptions=teamCache.get(String(id))||null;gapContext=gapCache.get(String(id))||null;renderDetail();return}const[d,e,g,t,cg]=await Promise.all([api(`/phase3/issues/${id}`),api(`/phase3/issues/${id}/events`),api(`/admin/issue-taxonomy/issues/${id}/routing-context`).catch(()=>({data:{}})),api(`/phase3/issues/${id}/team-options`).catch(()=>({data:{}})),api(`/admin/issue-taxonomy/issues/${id}/communication-gap-snapshot`).catch(()=>Promise.resolve(readGapSnapshot(id)))]);detail=d.data;events=e.data||[];recommendation=g.data?.issueContext||g.data||null;teamOptions=t.data||null;gapContext=cg;detailCache.set(String(id),{detail,events});contextCache.set(String(id),recommendation);teamCache.set(String(id),teamOptions);gapCache.set(String(id),gapContext);renderDetail()}catch(err){recommendation=null;toast(err.message,false)}}
  let monitoringPage=1;
  const monitoringPageSize=5;
  async function monitoringTimeline(issueId){
    try{const p=await api(`/phase3/issues/${issueId}/monitoring-periods`),periods=p.data||[];if(!periods.length)return '<div class="mt-3 text-[11px] text-slate-500">Belum ada periode monitoring.</div>';
      const rows=await Promise.all(periods.map(async period=>{let gap=null;try{gap=(await api(`/phase3/issues/${issueId}/monitoring-periods/${period.number}/gap`)).data}catch{}const ev=gap?.evidence||{},assessment=gap?.communicationGap?.semanticAssessment;return `<div class="mt-2 rounded-lg border border-slate-800 bg-slate-950/50 p-3"><div class="flex flex-wrap justify-between gap-2"><b class="text-xs">Monitoring #${period.number}</b><span class="text-[10px] ${period.status==='CLOSED'?'text-slate-400':'text-cyan-300'}">${period.status==='CLOSED'?'Selesai':'Aktif'}</span></div><div class="text-[10px] text-slate-500 mt-1">${fmt(period.started_at)} → ${period.ended_at?fmt(period.ended_at):'sekarang'}</div>${gap?`<div class="grid grid-cols-2 md:grid-cols-5 gap-2 mt-3 text-[10px]"><div>Online <b>${ev.online||0}</b></div><div>Cetak <b>${ev.print||0}</b></div><div>Sosial <b>${ev.social||0}</b></div><div>Owned <b>${ev.owned||0}</b></div><div>Total <b>${ev.total||0}</b></div></div><div class="mt-2 text-[11px]">Communication Gap: <b class="text-cyan-300">${esc(assessment?.status||'UNASSESSED')}</b></div>`:''}${period.close_note?`<div class="text-[10px] text-slate-500 mt-2">${esc(period.close_note)}</div>`:''}</div>`;}));return '<div class="mt-3"><div class="text-[10px] font-black tracking-wider text-slate-500">RIWAYAT PERIODE</div>'+rows.join('')+'</div>'}catch{return '<div class="mt-3 text-[11px] text-rose-300">Riwayat monitoring gagal dimuat.</div>'}}
  async function loadMonitoring(){const root=ensureSection();if(!root)return;try{const[me,res]=await Promise.all([api('/rbac/me'),api('/phase3/outcomes')]);currentUser=me.user||me.data||me;const rows=res.data||[],pages=Math.max(1,Math.ceil(rows.length/monitoringPageSize));monitoringPage=Math.min(Math.max(1,monitoringPage),pages);const visible=rows.slice((monitoringPage-1)*monitoringPageSize,monitoringPage*monitoringPageSize),timelines=await Promise.all(visible.map(x=>monitoringTimeline(x.issue_id)));root.innerHTML=`${submenu('monitoring')}<div class="glass rounded-2xl p-5"><div class="text-[10px] tracking-[.2em] text-cyan-400 font-black">PHASE 3 · RESPONSE OUTCOME</div><h2 class="text-xl font-black mt-1">Monitoring Respons</h2><p class="text-xs text-slate-400 mt-1">Setiap periode memakai evidence sejak monitoring dimulai sampai ditutup. Periode lama tetap menjadi histori.</p></div><div class="space-y-3">${visible.map((x,i)=>`<div class="glass rounded-xl p-4"><div class="flex flex-wrap justify-between gap-3"><div><div class="flex items-center gap-2">${badge(x.workflow_status)}<span class="text-[10px] text-slate-500">Issue #${esc(x.issue_id)}</span></div><div class="font-black mt-2">${esc(x.title)}</div><div class="text-xs text-slate-500 mt-1">Lead OPD: ${esc(x.lead_opd_name||'-')} · Disetujui: ${fmt(x.approved_at)}</div></div><div class="flex flex-wrap gap-2 items-start">${isHumas()&&x.workflow_status==='APPROVED'?`<button data-publish="${x.issue_id}" class="px-3 py-2 rounded-lg bg-emerald-400 text-slate-950 text-xs font-black">Catat Publikasi</button>`:''}${isHumas()&&x.workflow_status==='PUBLISHED'?`<button data-monitor="${x.issue_id}" class="px-3 py-2 rounded-lg bg-cyan-400 text-slate-950 text-xs font-black">Mulai Monitoring</button>`:''}${isHumas()&&x.workflow_status==='MONITORING'?`<button data-close="${x.issue_id}" class="px-3 py-2 rounded-lg bg-slate-700 text-slate-100 text-xs font-black">Tutup Monitoring</button>`:''}${isHumas()&&x.workflow_status==='CLOSED'?`<button data-monitor="${x.issue_id}" class="px-3 py-2 rounded-lg bg-cyan-500/15 border border-cyan-500/30 text-cyan-300 text-xs font-black">Buka Kembali Monitoring</button>`:''}</div></div>${x.publication?.channel?`<div class="mt-3 rounded-lg bg-slate-950/60 p-3 text-xs"><b>Publikasi:</b> ${esc(x.publication.channel)}${x.publication.url?` · <a class="text-cyan-300 underline break-all" href="${esc(x.publication.url)}" target="_blank" rel="noopener noreferrer">${esc(x.publication.url)}</a>`:''}</div>`:''}${timelines[i]}${x.close_note?`<div class="mt-2 text-xs text-slate-400">Catatan penutupan terakhir: ${esc(x.close_note)}</div>`:''}</div>`).join('')||'<div class="glass rounded-xl p-8 text-center text-sm text-slate-500">Belum ada respons yang disetujui untuk dimonitor.</div>'}</div>${rows.length>monitoringPageSize?`<div class="flex justify-center items-center gap-3 mt-4"><button id="monPrev" class="px-3 py-2 rounded-lg bg-slate-800 text-xs" ${monitoringPage<=1?'disabled':''}>Sebelumnya</button><span class="text-xs text-slate-500">Halaman ${monitoringPage} / ${pages}</span><button id="monNext" class="px-3 py-2 rounded-lg bg-slate-800 text-xs" ${monitoringPage>=pages?'disabled':''}>Berikutnya</button></div>`:''}`;bindSubmenu(root);root.querySelector('#monPrev')?.addEventListener('click',()=>{monitoringPage--;loadMonitoring()});root.querySelector('#monNext')?.addEventListener('click',()=>{monitoringPage++;loadMonitoring()});root.querySelectorAll('[data-publish]').forEach(b=>b.onclick=async()=>{const channel=prompt('Kanal publikasi: website, instagram, facebook, tiktok, youtube, x, threads, press_release, media_statement, other','website');if(!channel)return;const url=prompt('URL publikasi (boleh dikosongkan)','')||null,note=prompt('Catatan publikasi (opsional)','')||null;try{await api('/phase3/issues/'+b.dataset.publish+'/publish',{method:'POST',body:JSON.stringify({channel,url,note})});toast('Publikasi tercatat.');await loadMonitoring()}catch(e){toast(e.message,false)}});root.querySelectorAll('[data-monitor]').forEach(b=>b.onclick=async()=>{if(b.disabled)return;const old=b.innerHTML;b.disabled=true;b.innerHTML='<i class="fa-solid fa-spinner fa-spin mr-1"></i>Memproses...';try{await api('/phase3/issues/'+b.dataset.monitor+'/monitor',{method:'POST',body:JSON.stringify({})});toast('Periode monitoring dimulai.');await loadMonitoring()}catch(e){b.disabled=false;b.innerHTML=old;toast(e.message,false)}});root.querySelectorAll('[data-close]').forEach(b=>b.onclick=async()=>{const note=prompt('Alasan/catatan penutupan monitoring:','');if(!note)return;try{await api('/phase3/issues/'+b.dataset.close+'/close',{method:'POST',body:JSON.stringify({note})});toast('Monitoring ditutup.');await loadMonitoring()}catch(e){toast(e.message,false)}})}catch(e){root.innerHTML=`${submenu('monitoring')}<div class="glass rounded-2xl p-6 text-sm text-rose-300">Gagal memuat monitoring: ${esc(e.message)}</div>`;bindSubmenu(root)}}
  async function load(preserve=false){try{detailCache.clear();contextCache.clear();teamCache.clear();gapCache.clear();removeTopTab();activateCommunicationGapTab();const[me,list,opd]=await Promise.all([api('/rbac/me'),api('/phase3/issues'),api('/opd')]);currentUser=me.user||me.data||me;issues=list.data||[];opds=opd.data||[];if(!preserve||!issues.some(x=>String(x.issue_id)===String(selectedIssueId)))selectedIssueId=issues[0]?.issue_id||null;renderShell();if(selectedIssueId)await selectIssue(selectedIssueId)}catch(e){toast(e.message,false);const root=ensureSection();if(root)root.innerHTML=`${submenu('assignment')}<div class="glass rounded-2xl p-6 text-sm text-rose-300">Gagal memuat workflow: ${esc(e.message)}</div>`;bindSubmenu(root)}}
  window.openPhase3Workspace=()=>openSub('assignment');window.openCommunicationGapWorkspace=openSub;
  removeTopTab();
  const oldShow=window.showTab;if(typeof oldShow==='function'&&!oldShow.__phase3Submenu){const wrapped=function(id){if(id==='phase3')return openSub('assignment');return oldShow(id)};wrapped.__phase3Submenu=true;window.showTab=wrapped}
